//! Actual migrated, JWT-authenticated native workflows; no transport listeners or optional skip.
use axum::{body::{Body,to_bytes},http::{Request,StatusCode}};
use serde_json::{json,Value};use sqlx::{AnyPool,Connection};use tower::ServiceExt;
use std::{path::{Path,PathBuf},collections::BTreeMap,io::Read};use sha2::{Digest,Sha256};
const SPACE:&str="core-space";const PAGE:&str="core-page";const PUBLIC:&str="CORE_PUBLIC_BODY Ω café\n[stable reference](starlane://core-page)\n";const PRIVATE:&str="CORE_PRIVATE_BODY_DO_NOT_DISCLOSE";const JWT:&str="owned-core-runtime-fixture-secret";
fn workspace()->PathBuf{PathBuf::from(std::env::var("STARLANE_CORE_WORKSPACE").expect("required private core workspace"))}
async fn pool(url:&str,schema:&str)->AnyPool{sqlx::any::install_default_drivers();let engine=crate::db::DatabaseEngine::from_url(url).unwrap();let schema=schema.to_owned();sqlx::any::AnyPoolOptions::new().max_connections(2).after_connect(move|c,_|{let schema=schema.clone();Box::pin(async move{match engine{crate::db::DatabaseEngine::Postgres=>{sqlx::query(&format!("SET search_path TO {schema}")).execute(c).await?;},crate::db::DatabaseEngine::Sqlite=>{sqlx::query("PRAGMA foreign_keys=ON").execute(&mut*c).await?;sqlx::query("PRAGMA busy_timeout=5000").execute(c).await?;}}Ok(())})}).connect(url).await.unwrap()}
fn state(db:AnyPool,root:&Path)->crate::AppState{crate::AppState{db,jwt_secret:JWT.into(),base_url:"http://owned.invalid".into(),search_index:crate::search::SearchIndex::new(root.join("search_index")).unwrap(),oauth_cache:crate::auth::routes::OAuthStateCache::new(),ws_rooms:crate::sync::WsRooms::default()}}
fn bearer(actor:&str)->String{crate::auth::jwt::create_token_pair_for_session(actor,&format!("{actor}@core.invalid"),"member",JWT,Some(&format!("core-{actor}")),30).unwrap().access_token}
async fn call(s:&crate::AppState,actor:Option<&str>,method:&str,uri:&str,body:Value)->(StatusCode,Value){println!("CORE_STEP {} {method} {uri}",actor.unwrap_or("anonymous"));let mut q=Request::builder().method(method).uri(uri).header("Content-Type","application/json");if let Some(actor)=actor{q=q.header("Authorization",format!("Bearer {}",bearer(actor)));}let r=crate::api_routes().with_state(s.clone()).oneshot(q.body(Body::from(body.to_string())).unwrap()).await.unwrap();let code=r.status();let bytes=to_bytes(r.into_body(),8*1024*1024).await.unwrap();(code,if bytes.is_empty(){Value::Null}else{serde_json::from_slice(&bytes).unwrap_or(json!({"raw":String::from_utf8_lossy(&bytes)}))})}
async fn ok(s:&crate::AppState,actor:&str,method:&str,uri:&str,v:Value)->Value{let(code,v)=call(s,Some(actor),method,uri,v).await;assert!(code.is_success(),"{actor} {method} {uri}: {code} {v}");v}
async fn deny(s:&crate::AppState,actor:Option<&str>,method:&str,uri:&str,v:Value){let(code,v)=call(s,actor,method,uri,v).await;assert!(matches!(code,StatusCode::UNAUTHORIZED|StatusCode::FORBIDDEN|StatusCode::NOT_FOUND),"unexpected denial {code} {uri}: {v}");assert!(!v.to_string().contains(PRIVATE));}
fn page()->String{format!("/spaces/{SPACE}/documents/{PAGE}")}
async fn seed(db:&AnyPool){for actor in ["owner","editor","viewer","outsider","direct"]{sqlx::query("INSERT INTO users(id,email,display_name,role,account_kind) VALUES($1,$2,$1,'member','member')").bind(actor).bind(format!("{actor}@core.invalid")).execute(db).await.unwrap();sqlx::query("INSERT INTO sessions(id,user_id,refresh_token_hash,expires_at,session_kind) VALUES($1,$2,'not-a-token','2999-01-01T00:00:00Z','browser')").bind(format!("core-{actor}")).bind(actor).execute(db).await.unwrap();}sqlx::query("INSERT INTO spaces(id,name,slug,visibility,created_by) VALUES($1,'Core workflow','core-workflow','private','owner')").bind(SPACE).execute(db).await.unwrap();for(actor,role)in[("owner","owner"),("editor","editor"),("viewer","viewer")]{sqlx::query("INSERT INTO space_members(id,space_id,user_id,role) VALUES($1,$2,$3,$4)").bind(format!("core-membership-{actor}")).bind(SPACE).bind(actor).bind(role).execute(db).await.unwrap();}}
async fn create_page(s:&crate::AppState)->Value{let v=ok(s,"owner","POST",&format!("/spaces/{SPACE}/documents"),json!({"source_id":PAGE,"title":"Core stable page","content":PUBLIC,"property_values":[]})).await;assert_eq!(v["id"],PAGE);ok(s,"owner","POST",&format!("{}/drafts/{}/publish",page(),v["draft_id"].as_str().unwrap()),json!({})).await;v}
async fn grant(s:&crate::AppState,action:&str){let prefix=format!("{}/viewer-grants",page());let proposal=json!({"user_id":"direct","action":action});let review=ok(s,"owner","POST",&format!("{prefix}/review"),proposal.clone()).await;assert_eq!(ok(s,"owner","POST",&format!("{prefix}/confirm"),json!({"proposal":proposal,"source_digest":review["source_digest"],"confirm":true})).await["confirmed"],true);}
async fn page_audiences(s:&crate::AppState)->Value{
 create_page(s).await;let d=ok(s,"owner","POST",&format!("{}/drafts",page()),json!({})).await;let id=d["id"].as_str().unwrap();let uri=format!("{}/drafts/{id}",page());ok(s,"owner","PUT",&uri,json!({"source_digest":d["source_digest"],"content":PRIVATE})).await;ok(s,"owner","PUT",&format!("{uri}/access/editor"),json!({"role":"editor"})).await;
 for a in["owner","editor","viewer"]{assert!(ok(s,a,"GET",&format!("{}/content",page()),Value::Null).await["content"].as_str().unwrap().contains(PUBLIC));}
 for a in["owner","editor"]{assert_eq!(ok(s,a,"GET",&uri,Value::Null).await["content"],PRIVATE);}
 for a in[Some("viewer"),Some("outsider"),None]{deny(s,a,"GET",&uri,Value::Null).await;}
 for a in[Some("outsider"),None]{deny(s,a,"GET",&format!("{}/content",page()),Value::Null).await;}
 deny(s,Some("viewer"),"PUT",&uri,json!({"source_digest":d["source_digest"],"content":"ILLEGAL"})).await;
 grant(s,"grant").await;assert!(ok(s,"direct","GET",&format!("{}/content",page()),Value::Null).await["content"].as_str().unwrap().contains(PUBLIC));deny(s,Some("direct"),"GET",&uri,Value::Null).await;grant(s,"revoke").await;deny(s,Some("direct"),"GET",&format!("{}/content",page()),Value::Null).await;
 json!({"draft_id":id})
}
async fn properties(s:&crate::AppState)->Value{
 create_page(s).await;let uri=format!("/spaces/{SPACE}/properties");let p=ok(s,"owner","POST",&uri,json!({"source_id":"core-property","name":"Identity","property_type":"text"})).await;assert_eq!(p["id"],"core-property");let values=format!("{}/properties",page());ok(s,"owner","PUT",&values,json!({"values":[{"source_id":"core-property-value","property_id":"core-property","value":"EXACT_PROPERTY_VALUE"}]})).await;
 for a in["owner","editor","viewer"]{let rows=ok(s,a,"GET",&values,Value::Null).await;assert!(rows.as_array().unwrap().iter().any(|r|r["property_id"]=="core-property"&&r["value"]=="EXACT_PROPERTY_VALUE"));}
 deny(s,Some("viewer"),"PUT",&values,json!({"values":[{"property_id":"core-property","value":"ILLEGAL"}]})).await;deny(s,Some("outsider"),"GET",&values,Value::Null).await;
 ok(s,"editor","PUT",&values,json!({"values":[{"property_id":"core-property","value":"EDITOR_EXACT_VALUE"}]})).await;ok(s,"owner","PUT",&format!("{uri}/core-property"),json!({"name":"Identity renamed","property_type":"text"})).await;
 json!({"property_id":p["id"],"value":"EDITOR_EXACT_VALUE"})
}
fn template_body(id:&str,body:&str)->Value{json!({"source_id":id,"name":"Core template","description":"Exact description","content":body,"properties":{"owner":"preserved"},"tags":["core","identity"]})}
async fn templates(s:&crate::AppState)->Value{
 let prefix=format!("/spaces/{SPACE}/templates");let id="core-template";assert_eq!(ok(s,"owner","POST",&prefix,template_body(id,"INITIAL_TEMPLATE")).await["id"],id);let uri=format!("{prefix}/{id}");let d=ok(s,"editor","POST",&format!("{uri}/drafts"),json!({})).await;let draft_uri=format!("{uri}/drafts/{}",d["id"].as_str().unwrap());ok(s,"editor","PUT",&draft_uri,template_body(id,"EXACT_TEMPLATE_PUBLISHED Ω")).await;deny(s,Some("viewer"),"GET",&draft_uri,Value::Null).await;deny(s,Some("owner"),"POST",&format!("{draft_uri}/publish"),json!({})).await;ok(s,"editor","POST",&format!("{draft_uri}/publish"),json!({})).await;
 for a in["owner","editor","viewer"]{assert_eq!(ok(s,a,"GET",&uri,Value::Null).await["content"],"EXACT_TEMPLATE_PUBLISHED Ω");}
 deny(s,Some("outsider"),"GET",&uri,Value::Null).await;deny(s,Some("viewer"),"PUT",&uri,template_body(id,"ILLEGAL")).await;let rev=ok(s,"editor","GET",&format!("{uri}/revisions"),Value::Null).await;assert_eq!(rev.as_array().unwrap().len(),1);assert_eq!(rev[0]["revision_number"],1);json!({"template_id":id,"revision_id":rev[0]["id"]})
}
fn replay()->Value{json!({"schema_version":1,"provider":"core-real-provider","replay_contract":{"schema_version":1,"operation_order":"queued_at_ascending","idempotency_key":"operation.id","transport":"server-api","server_backends":["sqlite","postgresql"],"required_payload_status":"available","conflict_policy":"server_validates_version_and_permissions","web_canonical_store":"server-api"},"operation_count":1,"recovery_checkpoint_count":1,"recovery_checkpoints":[{"spaceId":SPACE,"sourceServerUrl":"http://owned.invalid","downloadedByUserId":"editor","cursor":"exact-checkpoint"}],"operations":[{"id":"core-replay-operation","entity_type":"template","entity_id":"core-replayed-template","action":"create","queued_at":"2026-10-10T00:00:00Z","payload_status":"available","payload":{"id":"core-replayed-template","space_id":SPACE,"name":"Replayed exact","content":"EXACT_REPLAY_BODY Ω","properties":{"source":"real"},"tags":["sync"],"created_at":"2026-10-10T00:00:00Z","updated_at":"2026-10-10T00:00:00Z"}}]})}
async fn sync_domain(db:&AnyPool)->BTreeMap<String,Vec<Value>>{
 use sqlx::{Column,Row};let mut out=BTreeMap::new();
 for table in ["templates","template_replay_receipts","sync_replay_operations"]{let mut values=Vec::new();for row in sqlx::query(&format!("SELECT * FROM {table}")).fetch_all(db).await.unwrap(){let mut cells=BTreeMap::new();for col in row.columns(){let n=col.name();let v=if let Ok(v)=row.try_get::<Option<String>,_>(n){v.map(|v|json!(["text",v])).unwrap_or(json!(["null"]))}else if let Ok(v)=row.try_get::<Option<i64>,_>(n){v.map(|v|json!(["integer",v.to_string()])).unwrap_or(json!(["null"]))}else if let Ok(v)=row.try_get::<Option<Vec<u8>>,_>(n){v.map(|v|json!(["blob",hex::encode(v)])).unwrap_or(json!(["null"]))}else{panic!("unsupported exact sync cell {table}.{n}")};cells.insert(n.to_string(),v);}values.push(serde_json::to_value(cells).unwrap());}values.sort_by_cached_key(Value::to_string);out.insert(table.into(),values);}out
}
async fn sync(s:&crate::AppState)->Value{
 assert_eq!(ok(s,"editor","POST","/sync/replay/preflight",replay()).await["ready"],true);
 let r=ok(s,"editor","POST","/sync/replay",replay()).await;assert_eq!(r["applied_operation_count"],1,"{r}");
 let ledger:(String,Option<String>,String,String)=sqlx::query_as("SELECT status,completed_at,attempted_by,payload FROM sync_replay_operations WHERE operation_id='core-replay-operation'").fetch_one(&s.db).await.unwrap();assert_eq!(ledger.0,"applied");chrono::DateTime::parse_from_rfc3339(ledger.1.as_deref().unwrap()).unwrap();assert_eq!(ledger.2,"editor");assert_eq!(serde_json::from_str::<Value>(&ledger.3).unwrap(),replay()["operations"][0]["payload"]);
 let before=sync_domain(&s.db).await;let file_bytes=bytes(&crate::storage::data_dir());
 let duplicate=ok(s,"editor","POST","/sync/replay",replay()).await;assert_eq!(duplicate["skipped_operation_count"],1,"{duplicate}");assert_eq!(sync_domain(&s.db).await,before);assert_eq!(bytes(&crate::storage::data_dir()),file_bytes);
 for actor in ["viewer","outsider"]{assert_eq!(ok(s,actor,"POST","/sync/replay",replay()).await["failed_operation_count"],1);assert_eq!(sync_domain(&s.db).await,before);assert_eq!(bytes(&crate::storage::data_dir()),file_bytes);}
 let mut conflict=replay();conflict["operations"][0]["payload"]["name"]=json!("CONFLICTING_SAME_OPERATION");assert_eq!(ok(s,"editor","POST","/sync/replay",conflict).await["failed_operation_count"],1);assert_eq!(sync_domain(&s.db).await,before);assert_eq!(bytes(&crate::storage::data_dir()),file_bytes);
 let row:(String,String,String,String)=sqlx::query_as("SELECT provider,incoming_id,entity_id,receipt_json FROM template_replay_receipts WHERE incoming_id='core-replay-operation'").fetch_one(&s.db).await.unwrap();assert_eq!(row.0,"core-real-provider");assert_eq!(row.2,"core-replayed-template");
 let history=ok(s,"editor","GET","/sync/replay/history",Value::Null).await;let manifests=history["manifests"].as_array().unwrap();assert_eq!(manifests.len(),3);for h in manifests{assert_eq!(h["attempted_by"],"editor");assert_eq!(h["recovery_checkpoint_count"],1);let checks=h["checkpoints"].as_array().unwrap();assert_eq!(checks.len(),1);assert_eq!(checks[0]["checkpoint"],replay()["recovery_checkpoints"][0]);assert_eq!(checks[0]["space_id"],SPACE);assert_eq!(checks[0]["downloaded_by_user_id"],"editor");}
 // Genuine committed domain mutation with lost HTTP acknowledgement: make only advisory history unavailable.
 let mut unknown=replay();unknown["operations"][0]["id"]=json!("core-unknown-operation");unknown["operations"][0]["entity_id"]=json!("core-unknown-template");unknown["operations"][0]["payload"]["id"]=json!("core-unknown-template");
 sqlx::query("ALTER TABLE sync_replay_manifests RENAME TO core_history_unavailable").execute(&s.db).await.unwrap();let(code,_)=call(s,Some("editor"),"POST","/sync/replay",unknown.clone()).await;assert_eq!(code,StatusCode::INTERNAL_SERVER_ERROR);sqlx::query("ALTER TABLE core_history_unavailable RENAME TO sync_replay_manifests").execute(&s.db).await.unwrap();
 let raw:String=sqlx::query_scalar("SELECT receipt_json FROM template_replay_receipts WHERE incoming_id='core-unknown-operation'").fetch_one(&s.db).await.unwrap();let original:String=sqlx::query_scalar("SELECT receipt_json FROM template_replay_receipts WHERE incoming_id='core-replay-operation'").fetch_one(&s.db).await.unwrap();assert_eq!(original,row.3);let committed=sync_domain(&s.db).await;
 let retry=ok(s,"editor","POST","/sync/replay",unknown).await;assert_eq!(retry["skipped_operation_count"],1,"{retry}");assert_eq!(sync_domain(&s.db).await,committed);assert_eq!(bytes(&crate::storage::data_dir()),file_bytes);assert_eq!(sqlx::query_scalar::<_,String>("SELECT receipt_json FROM template_replay_receipts WHERE incoming_id='core-unknown-operation'").fetch_one(&s.db).await.unwrap(),raw);
 println!("CORE_SYNC_EXACT_GATES ledger/applied/raw payload/checkpoint/history/current denied/conflicting/duplicate and genuine committed-domain-lost-ack retry preserved");json!({"receipt":row.3,"template_id":row.2,"unknown_receipt":raw,"domain":committed})
}

fn bytes(root:&Path)->BTreeMap<String,String>{fn walk(root:&Path,p:&Path,out:&mut BTreeMap<String,String>){let m=std::fs::symlink_metadata(p).unwrap();assert!(!m.file_type().is_symlink());if m.is_dir(){for e in std::fs::read_dir(p).unwrap(){walk(root,&e.unwrap().path(),out);}}else{assert!(m.is_file());let mut f=std::fs::File::open(p).unwrap();let mut h=Sha256::new();let mut b=[0u8;65536];loop{let n=f.read(&mut b).unwrap();if n==0{break}h.update(&b[..n]);}out.insert(p.strip_prefix(root).unwrap().to_string_lossy().into(),hex::encode(h.finalize()));}}let mut out=BTreeMap::new();for n in["spaces",".storage-journal",".publication-journal",".canonical-rewrite-journal",".move-relocation-journal"]{let p=root.join(n);if p.exists(){walk(root,&p,&mut out);}}out}
async fn run(engine:&str,kind:&str){let root=crate::storage::data_dir();assert!(root.starts_with(workspace()));std::fs::create_dir_all(&root).unwrap();let(url,schema)=if engine=="postgres"{let url=std::env::var("STARLANE_CORE_PG_URL").expect("required owned PG URL");assert!(url.starts_with("postgres://"));sqlx::any::install_default_drivers();let schema=format!("core_{}",uuid::Uuid::new_v4().simple());let mut c=sqlx::AnyConnection::connect(&url).await.unwrap();sqlx::query(&format!("CREATE SCHEMA {schema}")).execute(&mut c).await.unwrap();c.close().await.unwrap();(url,schema)}else{(format!("sqlite://{}?mode=rwc",root.join("starlane-notes.db").display()),String::new())};let db=pool(&url,&schema).await;crate::db::migrate_selected(&db,crate::db::DatabaseEngine::from_url(&url).unwrap()).await.unwrap();seed(&db).await;let s=state(db,&root);let expected=match kind{"audiences"=>page_audiences(&s).await,"properties"=>properties(&s).await,"templates"=>templates(&s).await,"sync"=>sync(&s).await,_=>panic!()};let evidence=json!({"kind":kind,"expected":expected,"bytes":bytes(&root)});std::fs::write(workspace().join("expected.json"),evidence.to_string()).unwrap();s.db.close().await;drop(s);let child=std::process::Command::new(std::env::current_exe().unwrap()).args(["postgres_core_fixture::fresh_core_child","--ignored","--exact","--nocapture"]).env("STARLANE_CORE_CHILD_URL",url).env("STARLANE_CORE_SCHEMA",schema).output().unwrap();assert!(child.status.success(),"{}\n{}",String::from_utf8_lossy(&child.stdout),String::from_utf8_lossy(&child.stderr));println!("CORE_FRESH_CHILD_PASS {}",String::from_utf8_lossy(&child.stdout));}
macro_rules! case{($name:ident,$engine:literal,$kind:literal)=>{#[tokio::test]#[ignore="required explicitly owned dual-engine core fixture orchestration"]async fn $name(){run($engine,$kind).await;}};}
case!(required_postgres_audiences,"postgres","audiences");case!(required_sqlite_audiences,"sqlite","audiences");case!(required_postgres_properties,"postgres","properties");case!(required_sqlite_properties,"sqlite","properties");case!(required_postgres_templates,"postgres","templates");case!(required_sqlite_templates,"sqlite","templates");case!(required_postgres_sync,"postgres","sync");case!(required_sqlite_sync,"sqlite","sync");
#[tokio::test]#[ignore="only required parent launches actual fresh process"]async fn fresh_core_child(){let url=std::env::var("STARLANE_CORE_CHILD_URL").expect("required genuine parent URL");let schema=std::env::var("STARLANE_CORE_SCHEMA").expect("required genuine parent schema");let root=crate::storage::data_dir();assert!(root.starts_with(workspace()));let evidence:Value=serde_json::from_slice(&std::fs::read(workspace().join("expected.json")).unwrap()).unwrap();let db=pool(&url,&schema).await;crate::storage::restoration::bootstrap_gate(&root).unwrap();crate::storage::restoration::activate_in(&root,&db).await.unwrap();crate::storage::relocation::recover(&db).await.unwrap();crate::storage::journal::recover(&db).await.unwrap();crate::storage::canonical_rewrite::recover(&db).await.unwrap();crate::storage::publication::recover(&db).await.unwrap();let s=state(db,&root);let e=&evidence["expected"];match evidence["kind"].as_str().unwrap(){"audiences"=>{for a in["owner","editor","viewer"]{assert!(ok(&s,a,"GET",&format!("{}/content",page()),Value::Null).await["content"].as_str().unwrap().contains(PUBLIC));}let uri=format!("{}/drafts/{}",page(),e["draft_id"].as_str().unwrap());for a in["owner","editor"]{assert_eq!(ok(&s,a,"GET",&uri,Value::Null).await["content"],PRIVATE);}for a in[Some("viewer"),Some("outsider"),None]{deny(&s,a,"GET",&uri,Value::Null).await;}deny(&s,Some("direct"),"GET",&format!("{}/content",page()),Value::Null).await;},"properties"=>{let rows=ok(&s,"viewer","GET",&format!("{}/properties",page()),Value::Null).await;assert!(rows.as_array().unwrap().iter().any(|r|r["property_id"]==e["property_id"]&&r["value"]==e["value"]));},"templates"=>{assert_eq!(ok(&s,"viewer","GET",&format!("/spaces/{SPACE}/templates/core-template"),Value::Null).await["content"],"EXACT_TEMPLATE_PUBLISHED Ω");assert_eq!(ok(&s,"editor","GET",&format!("/spaces/{SPACE}/templates/core-template/revisions"),Value::Null).await[0]["id"],e["revision_id"]);},"sync"=>{assert_eq!(serde_json::to_value(sync_domain(&s.db).await).unwrap(),e["domain"]);assert_eq!(ok(&s,"editor","POST","/sync/replay",replay()).await["skipped_operation_count"],1);assert_eq!(serde_json::to_value(sync_domain(&s.db).await).unwrap(),e["domain"]);let raw:String=sqlx::query_scalar("SELECT receipt_json FROM template_replay_receipts WHERE incoming_id='core-replay-operation'").fetch_one(&s.db).await.unwrap();assert_eq!(raw,e["receipt"].as_str().unwrap());assert_eq!(ok(&s,"viewer","GET",&format!("/spaces/{SPACE}/templates/core-replayed-template"),Value::Null).await["content"],"EXACT_REPLAY_BODY Ω");},_=>panic!()}assert_eq!(serde_json::to_value(bytes(&root)).unwrap(),evidence["bytes"],"canonical/retained immutable evidence bytes must survive restart");s.db.close().await;drop(s);println!("CORE_ACTUAL_FRESH_RESTART_PASS");}
